// Symptom: the radar feed and the locked card sit side by side in one row.
// Assumes the feed is a region named "Radar feed" and the card is a region named "Locked".
// Their parent container should stack them in a column, so assert the parent is not a row.
await page.goto('/ops/radar');
const feed = page.getByRole('region', { name: 'Radar feed' });
const locked = page.getByRole('region', { name: 'Locked' });
await expect(feed).toBeVisible();
await expect(locked).toBeVisible();
// Buggy build lays both out in a row (flex-direction: row); the fixed build stacks them (column).
await expect(feed.locator('xpath=..')).not.toHaveCSS('flex-direction', 'row');

```js
await page.goto('/ops/radar');
const feed = page.getByRole('region', { name: 'Radar feed' });
const locked = page.getByRole('region', { name: 'Locked card' });
await expect(feed).toBeVisible();
await expect(locked).toBeVisible();
const feedBox = await feed.boundingBox();
const lockedBox = await locked.boundingBox();
// Stacked: the locked card starts below the bottom edge of the feed.
// Side by side (the bug): their vertical ranges overlap.
expect(lockedBox.y).toBeGreaterThanOrEqual(feedBox.y + feedBox.height);
```

